  "Patient presents with acute chest pain and shortness of breath. Can we combine aspirin with warfarin?": {
    en: "Patient presents with acute chest pain and shortness of breath. Can we combine aspirin with warfarin?",
    hi: "मरीज़ को सीने में तेज दर्द और सांस लेने में तकलीफ है। क्या हम एस्पिरिन को वारफेरिन के साथ ले सकते हैं?",
    bn: "রোগীর তীব্র বুকে ব্যথা এবং শ্বাসকষ্ট রয়েছে। আমরা কি অ্যাসপিরিনের সাথে ওয়ারফারিন একত্রিত করতে পারি?",
    ta: "நோயாளிக்கு கடுமையான நெஞ்சு வலி மற்றும் மூச்சுத் திணறல் உள்ளது. ஆஸ்பிரினுடன் வார்ஃபரினை இணைக்கலாமா?",
    te: "రోగికి తీవ్రమైన ఛాతీ నొప్పి మరియు శ్వాస ఆడకపోవడం ఉంది. మేము ఆస్పిరిన్‌ను వార్ఫరిన్‌తో కలపవచ్చా?",
    mr: "रुग्णाला छातीत तीव्र वेदना आणि श्वास घेण्यास त्रास होत आहे. आम्ही वॉरफेरिनसोबत ॲस्पिरिन एकत्र करू शकतो का?",
    gu: "દર્દીને છાતીમાં તીવ્ર દુખાવો અને શ્વાસ લેવામાં તકલીફ છે. શું આપણે એસ્પિરિનને વોરફેરીન સાથે જોડી શકીએ?",
    kn: "ರೋಗಿಗೆ ತೀವ್ರ ಎದೆ ನೋವು ಮತ್ತು ಉಸಿರಾಟದ ತೊಂದರೆ ಇದೆ. ನಾವು ಆಸ್ಪಿರಿನ್ ಅನ್ನು ವಾರ್ಫರಿನ್ ಜೊತೆ ಸಂಯೋಜಿಸಬಹುದೇ?",
    ml: "രോഗിക്ക് കഠിനമായ നെഞ്ചുവേദനയും ശ്വാസതടസ്സവുമുണ്ട്. ആസ്പിരിനും വാർഫറിനും ഒരുമിച്ച് നൽകാൻ കഴിയുമോ?",
    pa: "ਮਰੀਜ਼ ਨੂੰ ਛਾਤੀ ਵਿੱਚ ਤੇਜ਼ ਦਰਦ ਅਤੇ ਸਾਹ ਲੈਣ ਵਿੱਚ ਤਕਲੀਫ਼ ਹੈ। ਕੀ ਅਸੀਂ ਐਸਪਰੀਨ ਨੂੰ ਵਾਰਫਰੀਨ ਨਾਲ ਮਿਲਾ ਸਕਦੇ ਹਾਂ?",
    or: "ରୋଗୀଙ୍କୁ ଛାତିରେ ତୀବ୍ର ଯନ୍ତ୍ରଣା ଏବଂ ନିଶ୍ୱାସ କଷ୍ଟ ଅଛି । ଆମେ ଆସ୍ପିରିନ୍ ସହିତ ୱାର୍ଫାରିନ୍ ମିଶାଇ ପାରିବା କି?"
  },
