    gu: "ઓક્સિજન સંતૃપ્તિ: ૯૮.૫%, FEV1: ૪.૮L, સ્પષ્ટ શ્વસન અવાજો.",
    kn: "ಆಮ್ಲಜನಕ ಮಟ್ಟ: 98.5%, FEV1: 4.8L, ಸ್ಪಷ್ಟ ಉಸಿರಾಟದ ಶಬ್ದಗಳು.",
    ml: "ഓക്സിജൻ സാച്ചുറേഷൻ: 98.5%, FEV1: 4.8L, വ്യക്തമായ ശ്വസന ശബ്ദങ്ങൾ.",
    pa: "ਆਕਸੀਜਨ ਸੰਤ੍ਰਿਪਤਾ: 98.5%, FEV1: 4.8L, ਸਾਫ਼ ਸਾਹ ਦੀਆਂ ਆਵਾਜ਼ਾਂ।",
