// ABHA Generator & Card
  "Ayushman Bharat Health Account (ABHA) Generator & Registry": {
    en: "Ayushman Bharat Health Account (ABHA) Generator & Registry",
    hi: "आयुष्मान भारत स्वास्थ्य खाता (ABHA) जनरेटर एवं रजिस्ट्री",
    bn: "আয়ুষ্মান ভারত স্বাস্থ্য অ্যাকাউন্ট (ABHA) জেনারেটর ও রেজিস্ট্রি",
    ta: "ஆயுஷ்மான் பாரத் சுகாதார கணக்கு (ABHA) உருவாக்கி & பதிவேடு",
    te: "ఆయుష్మాన్ భారత్ హెల్త్ అకౌంట్ (ABHA) జనరేటర్ & రిజిస్ట్రీ",
    mr: "आयुष्मान भारत आरोग्य खाते (ABHA) जनरेटर आणि नोंदणी",
    gu: "આયુષ્માન ભારત હેલ્થ એકાઉન્ટ (ABHA) જનરેટર અને રજિસ્ટ્રી",
    kn: "ಆಯುಷ್ಮಾನ್ ಭಾರತ್ ಆರೋಗ್ಯ ಖಾತೆ (ABHA) ಜನರೇಟರ್ ಮತ್ತು ನೋಂದಣಿ",
    ml: "ആയുഷ്മാൻ ഭാരത് ഹെൽത്ത് അക്കൗണ്ട് (ABHA) ജനറേറ്ററും രജിസ്ട്രിയും",
    pa: "ਆਯੁਸ਼ਮਾਨ ਭਾਰਤ ਸਿਹਤ ਖਾਤਾ (ABHA) ਜਨਰੇਟਰ ਅਤੇ ਰਜਿਸਟਰੀ",
    or: "ଆୟୁଷ୍ମାନ ଭାରତ ସ୍ୱାସ୍ଥ୍ୟ ଖାତା (ABHA) ଜେନେରେଟର ଏବଂ ରେଜିଷ୍ଟ୍ରି"
  },
  "Generate your official 14-digit ABDM-compliant health number to link hospital records, lab reports, and claim PM-JAY ₹5L annual coverage.": {
    en: "Generate your official 14-digit ABDM-compliant health number to link hospital records, lab reports, and claim PM-JAY ₹5L annual coverage.",
    hi: "अस्पताल के रिकॉर्ड, लैब रिपोर्ट को लिंक करने और PM-JAY ₹5 लाख वार्षिक कवरेज का दावा करने के लिए अपना आधिकारिक 14-अंकीय ABDM स्वास्थ्य नंबर बनाएं।",
    bn: "হাসপাতালের রেকর্ড ও ল্যাব রিপোর্ট লিঙ্ক করতে এবং PM-JAY ₹৫ লাখ বার্ষিক কভারেজ দাবি করতে ১৪-সংখ্যার ABDM স্বাস্থ্য নম্বর তৈরি করুন।",
    ta: "மருத்துவமனை பதிவுகள், ஆய்வக அறிக்கைகளை இணைக்கவும், PM-JAY ₹5 லட்சம் வருடாந்திர கவரேஜைப் பெறவும் உங்கள் 14 இலக்க ABDM எண்ணை உருவாக்கவும்.",
    te: "ఆసుపత్రి రికార్డులు, ల్యాబ్ నివేదికలను లింక్ చేయడానికి మరియు PM-JAY ₹5లక్షల వార్షిక కవరేజీని పొందడానికి మీ 14 అంకెల ABDM నంబర్‌ను రూపొందించండి.",
    mr: "रुग्णालय नोंदी, लॅब अहवाल लिंक करण्यासाठी आणि PM-JAY ₹५ लाख वार्षिक कव्हरेज मिळवण्यासाठी तुमचा १४-अंकी ABDM आरोग्य क्रमांक तयार करा.",
    gu: "હોસ્પિટલના રેકોર્ડ્સ, લેબ રિપોર્ટ્સ લિંક કરવા અને PM-JAY ₹૫ લાખ વાર્ષિક કવરેજનો દાવો કરવા માટે તમારો ૧૪-અંકનો ABDM નંબર બનાવો.",
    kn: "ಆಸ್ಪತ್ರೆ ದಾಖಲೆಗಳು, ಲ್ಯಾಬ್ ವರದಿಗಳನ್ನು ಲಿಂಕ್ ಮಾಡಲು ಮತ್ತು PM-JAY ₹5 ಲಕ್ಷ ವಾರ್ಷಿಕ ಕವರೇಜ್ ಪಡೆಯಲು ನಿಮ್ಮ 14-ಅಂಕಿಯ ABDM ಸಂಖ್ಯೆಯನ್ನು ರಚಿಸಿ.",
    ml: "ആശുപത്രി രേഖകളും ലാബ് റിപ്പോർട്ടുകളും ബന്ധിപ്പിക്കുന്നതിനും PM-JAY ₹5 ലക്ഷം കവറേജ് ക്ലെയിം ചെയ്യുന്നതിനും നിങ്ങളുടെ 14 അക്ക ABDM നമ്പർ സൃഷ്ടിക്കുക.",
    pa: "ਹਸਪਤਾਲ ਦੇ ਰਿਕਾਰਡ, ਲੈਬ ਰਿਪੋਰਟਾਂ ਨੂੰ ਲਿੰਕ ਕਰਨ ਅਤੇ PM-JAY ₹5 ਲੱਖ ਸਾਲਾਨਾ ਕਵਰੇਜ ਪ੍ਰਾਪਤ ਕਰਨ ਲਈ ਆਪਣਾ 14-ਅੰਕੀ ABDM ਨੰਬਰ ਬਣਾਓ।",
    or: "ଡାକ୍ତରଖାନା ରେକର୍ଡ, ଲ୍ୟାବ୍ ରିପୋର୍ଟ ଲିଙ୍କ୍ କରିବା ଏବଂ PM-JAY ₹୫ ଲକ୍ଷ ବାର୍ଷିକ କଭରେଜ୍ ପାଇବା ପାଇଁ ଆପଣଙ୍କର ୧୪-ଅଙ୍କ ବିଶିଷ୍ଟ ABDM ନମ୍ବର ତିଆରି କରନ୍ତୁ ।"
  },
